    /**
     * Method to retrieve the Risk via RiskFetchOneSummary
     * @param 	summary RiskFetchOneSummary 
     * @return 	RiskFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Risk getRisk( RiskFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "RiskFetchOneSummary arg cannot be null" );
    	
    	Risk entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Risk
        	// --------------------------------------
        	CompletableFuture<Risk> futureEntity = queryGateway.query(new FindRiskQuery( new LoadRiskFilter( summary.getRiskId() ) ), ResponseTypes.instanceOf(Risk.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Risk with id " + summary.getRiskId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


